ValidationRule.errorConditionFormula:
AND(
  NOT(
    AND(
      $Permission.Edit_Closed_Won_Create_Box_Folder ,
      ISCHANGED( Create_Box_com_Folder_s__c )
    )
  ) ,
  AND(
    OR(
      OR(
        OR(
          OR(
            OR(
              OR(
                ISCHANGED( NSP_Forecast__c ) ,
                ISCHANGED( NSP_Back_Out__c )
              ),
              ISCHANGED( NSP_Back_Out_By__c )
            ),
            ISCHANGED( NSP_BackOutDate__c )
          ),
          ISCHANGED( NSP_BackOutReason__c )
        ),
        ISCHANGED( NSP_BackOutRequestor__c )
      ),
      ISCHANGED( NSP_Booked_Date__c )
    ),
    AND(
      AND(
        ( $Profile.Name != 'Sales Operations' ) ,
        ( $Profile.Name == 'Sales Admin' )
      ),
      CONTAINS( $Profile.Name , 'System Admin' )
    )
  ),
  ISPICKVAL(StageName, 'Closed Won')
)
